import * as THREE from 'three';

export interface Vector3f {
  x: number;
  y: number;
  z: number;
}

export interface BBox {
  minX: number;
  maxX: number;
  minY: number;
  maxY: number;
}

export interface HitResult {
  hit: boolean;
  entityA?: THREE.Object3D | null;
  entityB?: THREE.Object3D | null;
  normal?: THREE.Vector3;
  depth?: number;
}

export interface GameEvent {
  type: 'EXPLOSION' | 'PLAYER_HIT' | 'UFO_DESTROYED' | 'POWERUP_COLLECT' | 'LEVEL_COMPLETE';
  position?: Vector3f;
  intensity?: number;
  score?: number;
}

export interface PoolItem<T> {
  object: T;
  active: boolean;
}

export interface AudioConfig {
  frequency: number;
  type: OscillatorType;
  gain: number;
  duration: number;
  decayRate?: number;
}

export enum InvaderType {
  TYPE_0 = 0, // Top row - highest value
  TYPE_1 = 1, // Middle rows
  TYPE_2 = 2, // Bottom rows
}

export const INVADER_SCORES: Record<InvaderType, number> = {
  [InvaderType.TYPE_0]: 30,
  [InvaderType.TYPE_1]: 20,
  [InvaderType.TYPE_2],
};

export enum GameState {
  MENU = 'MENU',
  PLAYING = 'PLAYING',
  GAME_OVER = 'GAME_OVER',
  LEVEL_TRANSITION = 'LEVEL_TRANSITION',
}

import * as THREE from 'three';
import type { BBox, Vector3f } from '../types.js';

export function createAABB(
  x: number, y: number, w: number, h: number
): BBox {
  return { minX: x - w / 2, maxX: x + w / 2, minY: y - h / 2, maxY: y + h / 2 };
}

export function aabbOverlap(a: BBox, b: BBox): boolean {
  return a.minX < b.maxX && a.maxX > b.minX && a.minY < b.maxY && a.maxY > b.minY;
}

export function boxContainsPoint(box: BBox, px: number, py: number): boolean {
  return px >= box.minX && px <= box.maxX && py >= box.minY && py <= box.maxY;
}

export function worldToBBox(obj: THREE.Object3D, halfW: number, halfH: number): BBox {
  const pos = obj.position;
  return createAABB(pos.x, pos.y, halfW * 2, halfH * 2);
}

export function bBoxToWorld(box: BBox): Vector3f {
  return { x: (box.minX + box.maxX) / 2, y: (box.minY + box.maxY) / 2, z: 0 };
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

const GAMEPAD_INDEX = 0;
const DEAD_ZONE = 0.12;
const MAPPEd_RANGE = 1.0;

function clamp(v: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, v));
}

export class GamepadAPI {
  private connected: boolean = false;
  private axisX: number = 0;
  private axisY: number = 0;
  private buttonFire: boolean = false;
  private prevButtonFire: boolean = false;
  private pollInterval: number | null = null;

  get isGamepadConnected(): boolean { return this.connected; }
  get axisXRaw(): number { return this.axisX; }
  get axisYRaw(): number { return this.axisY; }
  get firePressed(): boolean { return this.buttonFire; }
  get fireJustPressed(): boolean { return this.buttonFire && !this.prevButtonFire; }

  private updateGamepad(): void {
    const gamepads = navigator.gamepads || (navigator as any).webkitGamepads;
    if (!gamepads) {
      this.connected = false;
      this.axisX = 0;
      this.axisY = 0;
      this.buttonFire = false;
      return;
    }

    const gp = gamepads[GAMEPAD_INDEX];
    if (!gp) {
      this.connected = false;
      this.axisX = 0;
      this.axisY = 0;
      this.buttonFire = false;
      return;
    }

    this.connected = true;

    // Left stick X (axis 0)
    let rawX = gp.axes[0] ?? 0;
    if (Math.abs(rawX) < DEAD_ZONE) rawX = 0;
    else rawX = clamp(rawX * MAPPEd_RANGE, -1, 1);

    // Left stick Y (axis 1) — inverted for game coords (up = positive)
    let rawY = -(gp.axes[1] ?? 0);
    if (Math.abs(rawY) < DEAD_ZONE) rawY = 0;
    else rawY = clamp(rawY * MAPPEd_RANGE, -1, 1);

    this.axisX = rawX;
    this.axisY = rawY;

    // Button mapping: A = fire (usually button 0), or South face
    this.buttonFire = false;
    if (gp.buttons.length > 0) {
      const btnA = gp.buttons[0];
      if (btnA && typeof btnA === 'object' && 'pressed' in btnA && (btnA as any).pressed) {
        this.buttonFire = true;
      }
    }
    // Also check D-pad (common mappings: 12=down, 13=left, 14=right, 15=up)
    if (!this.buttonFire && gp.buttons.length > 12) {
      for (let i = 12; i <= 15; i++) {
        const btn = gp.buttons[i];
        if (btn && typeof btn === 'object' && 'pressed' in btn && (btn as any).pressed) {
          this.buttonFire = true;
          break;
        }
      }
    }

    this.prevButtonFire = this.buttonFire;
  }

  startPolling(): void {
    if (this.pollInterval !== null) return;
    const tick = () => {
      this.updateGamepad();
      this.pollInterval = requestAnimationFrame(tick);
    };
    this.pollInterval = requestAnimationFrame(tick);
  }

  stopPolling(): void {
    if (this.pollInterval !== null) {
      cancelAnimationFrame(this.pollInterval);
      this.pollInterval = null;
    }
    this.connected = false;
    this.axisX = 0;
    this.axisY = 0;
    this.buttonFire = false;
  }

  dispose(): void {
    this.stopPolling();
  }
}

import { GamepadAPI } from './GamepadAPI.js';

export class InputManager {
  private keys: Set<string> = new Set();
  private justPressed: Set<string> = new Set();
  public gamepad: GamepadAPI;
  private animFrameId: number | null = null;

  constructor() {
    this.gamepad = new GamepadAPI();
    window.addEventListener('keydown', (e: KeyboardEvent) => {
      if (!this.keys.has(e.code)) {
        this.justPressed.add(e.code);
      }
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e: KeyboardEvent) => {
      this.keys.delete(e.code);
    });
  }

  startPolling(): void {
    this.gamepad.startPolling();
    const tick = () => {
      this.animFrameId = requestAnimationFrame(tick);
    };
    this.animFrameId = requestAnimationFrame(tick);
  }

  stopPolling(): void {
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
      this.animFrameId = null;
    }
    this.gamepad.stopPolling();
  }

  isDown(code: string): boolean {
    return this.keys.has(code);
  }

  justPressed(code: string): boolean {
    const result = this.justPressed.has(code);
    if (result) this.justPressed.delete(code);
    return result;
  }

  get horizontalInput(): number {
    let val = 0;
    if (this.isDown('KeyA') || this.isDown('ArrowLeft')) val -= 1;
    if (this.isDown('KeyD') || this.isDown('ArrowRight')) val += 1;
    // Gamepad override: stick takes priority over keys
    if (Math.abs(this.gamepad.axisXRaw) > 0.1) {
      val = Math.sign(this.gamepad.axisXRaw);
    }
    return val;
  }

  get fireInput(): boolean {
    return this.isDown('Space') || this.gamepad.firePressed;
  }

  get fireJustPressed(): boolean {
    return this.justPressed('Space') || this.gamepad.fireJustPressed;
  }

  dispose(): void {
    this.stopPolling();
    this.keys.clear();
    this.justPressed.clear();
    this.gamepad.dispose();
  }
}

import type { AudioConfig } from '../types.js';

export const SYNTH_PRESETS: Record<string, AudioConfig> = {
  LASER: { frequency: 880, type: 'square' as OscillatorType, gain: 0.15, duration: 0.1, decayRate: 0.5 },
  EXPLOSION: { frequency: 100, type: 'sawtooth' as OscillatorType, gain: 0.3, duration: 0.4, decayRate: 0.8 },
  UFO_LASER: { frequency: 220, type: 'triangle' as OscillatorType, gain: 0.1, duration: 0.2, decayRate: 0.6 },
  POWERUP: { frequency: 440, type: 'sine' as OscillatorType, gain: 0.2, duration: 0.3, decayRate: 0.3 },
  PLAYER_HIT: { frequency: 80, type: 'square' as OscillatorType, gain: 0.25, duration: 0.5, decayRate: 0.9 },
  INVADER_MARCH: { frequency: 60, type: 'sine' as OscillatorType, gain: 0.05, duration: 0.05, decayRate: 1.0 },
  UFO_APPEAR: { frequency: 330, type: 'sawtooth' as OscillatorType, gain: 0.2, duration: 0.8, decayRate: 0.4 },
};

import type { AudioConfig } from '../types.js';
import { SYNTH_PRESETS } from './SynthPresets.js';

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private enabled: boolean = false;

  constructor() {
    try {
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.3;
      this.masterGain.connect(this.ctx.destination);
      this.enabled = true;
    } catch {
      console.warn('Web Audio API not available');
    }
  }

  play(name: string, override?: Partial<AudioConfig>): void {
    if (!this.enabled || !this.ctx || !this.masterGain) return;
    const preset = SYNTH_PRESETS[name];
    if (!preset) return;
    const config: AudioConfig = { ...preset, ...override };

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = config.type;
    osc.frequency.setValueAtTime(config.frequency, this.ctx.currentTime);
    gain.gain.setValueAtTime(config.gain, this.ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + config.duration);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start();
    osc.stop(this.ctx.currentTime + config.duration);
  }

  playLaser(): void { this.play('LASER'); }
  playExplosion(): void { this.play('EXPLOSION'); }
  playUfoLaser(): void { this.play('UFO_LASER'); }
  playPowerup(): void { this.play('POWERUP'); }
  playPlayerHit(): void { this.play('PLAYER_HIT'); }
  playMarch(): void { this.play('INVADER_MARCH'); }
  playUfoAppear(): void { this.play('UFO_APPEAR'); }

  dispose(): void {
    if (this.ctx) {
      this.ctx.close();
      this.ctx = null;
    }
    this.enabled = false;
  }
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

const MAX_PARTICLES = 500;

interface ParticleConfig {
  position: Vector3f;
  velocity: Vector3f;
  color: number;
  size: number;
  life: number;
}

export class ParticleManager {
  private particles: THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial>;
  private positions: Float32Array;
  private colors: Float32Array;
  private sizes: Float32Array;
  private velocities: Float32Array;
  private lifetimes: Float32Array;
  private activeCount: number = 0;
  private maxCapacity: number;

  constructor(scene: THREE.Scene, color: THREE.Color = new THREE.Color(0x00ffff)) {
    const geometry = new THREE.BufferGeometry();
    this.maxCapacity = MAX_PARTICLES;
    this.positions = new Float32Array(this.maxCapacity * 3);
    this.colors = new Float32Array(this.maxCapacity * 3);
    this.sizes = new Float32Array(this.maxCapacity);
    this.velocities = new Float32Array(this.maxCapacity * 3);
    this.lifetimes = new Float32Array(this.maxCapacity);

    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
    geometry.setAttribute('size', new THREE.BufferAttribute(this.sizes, 1));

    const material = new THREE.PointsMaterial({
      size: 0.15,
      vertexColors: true,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true,
    });

    this.particles = new THREE.Points(geometry, material);
    scene.add(this.particles);
  }

  spawn(config: ParticleConfig): void {
    if (this.activeCount >= this.maxCapacity) return;

    const idx = this.activeCount;
    this.positions[idx * 3] = config.position.x;
    this.positions[idx * 3 + 1] = config.position.y;
    this.positions[idx * 3 + 2] = config.position.z || 0;

    this.velocities[idx * 3] = config.velocity.x;
    this.velocities[idx * 3 + 1] = config.velocity.y;
    this.velocities[idx * 3 + 2] = config.velocity.z || 0;

    const c = new THREE.Color(config.color);
    this.colors[idx * 3] = c.r;
    this.colors[idx * 3 + 1] = c.g;
    this.colors[idx * 3 + 2] = c.b;

    this.sizes[idx] = config.size;
    this.lifetimes[idx] = config.life;

    this.activeCount++;
  }

  update(dt: number): void {
    const geometry = this.particles.geometry as THREE.BufferGeometry;
    for (let i = this.activeCount - 1; i >= 0; i--) {
      this.lifetimes[i] -= dt;
      if (this.lifetimes[i] <= 0) {
        // Swap with last active particle
        const lastIdx = this.activeCount - 1;
        if (i !== lastIdx) {
          this.positions[i * 3] = this.positions[lastIdx * 3];
          this.positions[i * 3 + 1] = this.positions[lastIdx * 3 + 1];
          this.positions[i * 3 + 2] = this.positions[lastIdx * 3 + 2];
          this.velocities[i * 3] = this.velocities[lastIdx * 3];
          this.velocities[i * 3 + 1] = this.velocities[lastIdx * 3 + 1];
          this.velocities[i * 3 + 2] = this.velocities[lastIdx * 3 + 2];
          this.colors[i * 3] = this.colors[lastIdx * 3];
          this.colors[i * 3 + 1] = this.colors[lastIdx * 3 + 1];
          this.colors[i * 3 + 2] = this.colors[lastIdx * 3 + 2];
          this.sizes[i] = this.sizes[lastIdx];
          this.lifetimes[i] = this.lifetimes[lastIdx];
        }
        this.activeCount--;
      } else {
        // Update position with velocity and gravity
        const lifeRatio = this.lifetimes[i] / Math.max(0.01, this.sizes[i]);
        this.positions[i * 3] += this.velocities[i * 3] * dt;
        this.positions[i * 3 + 1] += this.velocities[i * 3 + 1] * dt - 2.0 * dt;
        // Fade color based on remaining life
        const fade = Math.max(0, lifeRatio);
        this.colors[i * 3] *= (0.95 + 0.05 * fade);
        this.colors[i * 3 + 1] *= (0.95 + 0.05 * fade);
        this.colors[i * 3 + 2] *= (0.95 + 0.05 * fade);
      }
    }

    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.color.needsUpdate = true;
  }

  get particleSystem(): THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial> {
    return this.particles;
  }

  dispose(): void {
    const geometry = this.particles.geometry as THREE.BufferGeometry;
    geometry.dispose();
    (this.particles.material as THREE.Material).dispose();
    this.particles.clearGroups();
  }
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

export class CameraShake {
  private intensity: number = 0;
  private decayRate: number = 5.0;
  private offset: Vector3f = { x: 0, y: 0, z: 0 };
  private camera: THREE.PerspectiveCamera | THREE.OrthographicCamera;

  constructor(camera: THREE.PerspectiveCamera | THREE.OrthographicCamera) {
    this.camera = camera;
  }

  trigger(intensity: number): void {
    this.intensity = Math.max(this.intensity, intensity);
  }

  update(dt: number): Vector3f {
    if (this.intensity > 0.001) {
      this.intensity *= Math.exp(-this.decayRate * dt);
      const range = this.intensity;
      this.offset.x = (Math.random() - 0.5) * range;
      this.offset.y = (Math.random() - 0.5) * range;
      this.offset.z = (Math.random() - 0.5) * range * 0.3;
    } else {
      this.intensity = 0;
      this.offset.x = 0;
      this.offset.y = 0;
      this.offset.z = 0;
    }

    if (this.camera) {
      this.camera.position.x += this.offset.x - (this.camera.userData.prevOffsetX || 0);
      this.camera.position.y += this.offset.y - (this.camera.userData.prevOffsetY || 0);
      this.camera.userData.prevOffsetX = this.offset.x;
      this.camera.userData.prevOffsetY = this.offset.y;
    }

    return { x: this.offset.x, y: this.offset.y, z: this.offset.z };
  }

  reset(): void {
    this.intensity = 0;
    this.offset.x = 0;
    this.offset.y = 0;
    this.offset.z = 0;
  }

  dispose(): void {
    // No resources to clean up
  }
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

export class CameraShake {
  private intensity: number = 0;
  private decayRate: number = 5.0;
  private offset: Vector3f = { x: 0, y: 0, z: 0 };
  private camera: THREE.PerspectiveCamera | THREE.OrthographicCamera;
  private basePosition: { x: number; y: number; z: number } = { x: 0, y: 0, z: 0 };

  constructor(camera: THREE.PerspectiveCamera | THREE.OrthographicCamera) {
    this.camera = camera;
    if (camera) {
      this.basePosition.x = camera.position.x;
      this.basePosition.y = camera.position.y;
      this.basePosition.z = camera.position.z;
    }
  }

  trigger(intensity: number): void {
    this.intensity = Math.max(this.intensity, intensity);
  }

  update(dt: number): Vector3f {
    if (this.intensity > 0.001) {
      this.intensity *= Math.exp(-this.decayRate * dt);
      const range = this.intensity;
      this.offset.x = (Math.random() - 0.5) * range;
      this.offset.y = (Math.random() - 0.5) * range;
      this.offset.z = (Math.random() - 0.5) * range * 0.3;
    } else {
      this.intensity = 0;
      this.offset.x = 0;
      this.offset.y = 0;
      this.offset.z = 0;
    }

    if (this.camera) {
      this.camera.position.x = this.basePosition.x + this.offset.x;
      this.camera.position.y = this.basePosition.y + this.offset.y;
      this.camera.position.z = this.basePosition.z + this.offset.z;
    }

    return { x: this.offset.x, y: this.offset.y, z: this.offset.z };
  }

  reset(): void {
    this.intensity = 0;
    this.offset.x = 0;
    this.offset.y = 0;
    this.offset.z = 0;
  }

  dispose(): void {
    // No resources to clean up
  }
}

export class HitStop {
  private framesRemaining: number = 0;
  private totalFrames: number = 0;

  constructor() {}

  trigger(frames: number = 4): void {
    this.framesRemaining += frames;
    this.totalFrames = Math.max(this.totalFrames, frames);
  }

  get timescale(): number {
    return this.framesRemaining > 0 ? 0.1 : 1.0;
  }

  update(dt: number): void {
    if (this.framesRemaining > 0) {
      // dt is in seconds, assume ~60fps so each frame ≈ 0.0167s
      this.framesRemaining -= dt / 0.0167;
      if (this.framesRemaining < 0) this.framesRemaining = 0;
    }
  }

  get isActive(): boolean {
    return this.framesRemaining > 0;
  }

  reset(): void {
    this.framesRemaining = 0;
  }
}

import * as THREE from 'three';

interface TrailPoint {
  position: THREE.Vector3;
  opacity: number;
}

export class MotionTrail {
  private points: TrailPoint[] = [];
  private maxPoints: number;
  private geometry: THREE.BufferGeometry;
  private material: THREE.LineBasicMaterial;
  private line: THREE.Line;
  private active: boolean = false;
  private color: THREE.Color;

  constructor(color: number = 0x00ffff, maxPoints: number = 20) {
    this.maxPoints = maxPoints;
    this.color = new THREE.Color(color);
    this.geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(maxPoints * 3);
    const opacities = new Float32Array(maxPoints);
    this.geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.geometry.setAttribute('opacity', new THREE.BufferAttribute(opacities, 1));

    this.material = new THREE.LineBasicMaterial({
      color: this.color,
      transparent: true,
      opacity: 0.5,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });

    this.line = new THREE.Line(this.geometry, this.material);
    this.line.frustumCulled = false;
  }

  addPoint(pos: THREE.Vector3): void {
    if (!this.active) return;
    this.points.unshift({ position: pos.clone(), opacity: 1.0 });
    if (this.points.length > this.maxPoints) {
      this.points.pop();
    }
    this.updateGeometry();
  }

  updateGeometry(): void {
    const positions = this.geometry.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < this.maxPoints; i++) {
      if (i < this.points.length) {
        positions.array[i * 3] = this.points[i].position.x;
        positions.array[i * 3 + 1] = this.points[i].position.y;
        positions.array[i * 3 + 2] = this.points[i].position.z;
      } else {
        positions.array[i * 3] = 0;
        positions.array[i * 3 + 1] = -9999;
        positions.array[i * 3 + 2] = 0;
      }
    }
    positions.needsUpdate = true;
  }

  update(dt: number): void {
    for (let i = this.points.length - 1; i >= 0; i--) {
      this.points[i].opacity -= dt * 3.0;
      if (this.points[i].opacity <= 0) {
        this.points.splice(i, 1);
      }
    }
  }

  get mesh(): THREE.Line {
    return this.line;
  }

  isActive(): boolean {
    return this.active && this.points.length > 1;
  }

  start(): void {
    this.active = true;
    this.points = [];
  }

  stop(): void {
    this.active = false;
    this.points = [];
  }

  dispose(): void {
    this.geometry.dispose();
    this.material.dispose();
  }
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

export class ShockwaveRing {
  private mesh: THREE.Mesh;
  private life: number = 0;
  private maxLife: number = 0.6;
  private active: boolean = false;
  private scene: THREE.Scene;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    const geometry = new THREE.RingGeometry(0.1, 0.3, 32);
    const material = new THREE.MeshBasicMaterial({
      color: 0x00ffff,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    });
    this.mesh = new THREE.Mesh(geometry, material);
    this.mesh.visible = false;
  }

  spawn(position: Vector3f, color: number = 0x00ffff): void {
    this.mesh.position.set(position.x, position.y, position.z || 0);
    this.mesh.material.color.set(color);
    this.mesh.scale.set(0.01, 0.01, 0.01);
    this.mesh.material.opacity = 0.8;
    this.mesh.visible = true;
    this.life = this.maxLife;
    this.active = true;
    this.scene.add(this.mesh);
  }

  update(dt: number): void {
    if (!this.active) return;
    this.life -= dt;
    const progress = 1 - (this.life / this.maxLife);
    const scale = progress * 8.0;
    this.mesh.scale.set(scale, scale, scale);
    this.mesh.material.opacity = Math.max(0, 0.8 * (1 - progress));

    if (this.life <= 0) {
      this.active = false;
      this.mesh.visible = false;
    }
  }

  get isActive(): boolean {
    return this.active;
  }

  dispose(): void {
    this.scene.remove(this.mesh);
    this.mesh.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}

import * as THREE from 'three';
import type { Vector3f } from '../types.js';

interface FloatingScoreEntry {
  element: HTMLElement;
  position: Vector3f;
  velocity: Vector3f;
  life: number;
  maxLife: number;
}

export class FloatingScoreText {
  private container: HTMLElement;
  private entries: FloatingScoreEntry[] = [];
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera | THREE.OrthographicCamera;

  constructor(scene: THREE.Scene, camera: THREE.PerspectiveCamera | THREE.OrthographicCamera) {
    this.scene = scene;
    this.camera = camera;
    this.container = document.getElementById('hud-overlay') || document.body;
  }

  spawn(position: Vector3f, score: number): void {
    const el = document.createElement('div');
    el.className = 'floating-score';
    el.textContent = `+${score}`;
    el.style.left = `${position.x}px`;
    el.style.top = `${position.y}px`;
    this.container.appendChild(el);

    this.entries.push({
      element: el,
      position: { x: position.x, y: position.y, z: 0 },
      velocity: { x: 0, y: 60, z: 0 },
      life: 1.0,
      maxLife: 1.0,
    });
  }

  update(dt: number): void {
    for (let i = this.entries.length - 1; i >= 0; i--) {
      const entry = this.entries[i];
      entry.life -= dt;
      entry.position.y += entry.velocity.y * dt;

      if (entry.life <= 0) {
        entry.element.remove();
        this.entries.splice(i, 1);
      } else {
        const opacity = Math.max(0, entry.life / entry.maxLife);
        entry.element.style.opacity = String(opacity);
        // Project 3D position to screen space for smooth follow
        const vec = new THREE.Vector3(entry.position.x, entry.position.y, 0.5);
        vec.project(this.camera);
        const x = (vec.x * 0.5 + 0.5) * window.innerWidth;
        const y = (-vec.y * 0.5 + 0.5) * window.innerHeight;
        entry.element.style.left = `${x}px`;
        entry.element.style.top = `${y - 20}px`;
      }
    }
  }

  dispose(): void {
    this.entries.forEach(e => e.element.remove());
    this.entries = [];
  }
}

import * as THREE from 'three';

export interface PooledObject<T> {
  object: T;
  active: boolean;
}

export class ObjectPool<T extends THREE.Object3D> {
  private pool: T[] = [];
  private activeList: T[] = [];
  private factory: () => T;
  private maxCapacity: number;

  constructor(factory: () => T, maxCapacity: number = 100) {
    this.factory = factory;
    this.maxCapacity = maxCapacity;
  }

  acquire(): T | null {
    // Try to reuse an inactive object from the pool
    for (let i = 0; i < this.pool.length; i++) {
      const obj = this.pool[i];
      if (!obj.userData.active) {
        obj.visible = true;
        obj.userData.active = true;
        this.activeList.push(obj);
        return obj;
      }
    }

    // Pool is exhausted, create a new one if under capacity
    if (this.pool.length < this.maxCapacity) {
      const newObj = this.factory();
      newObj.visible = true;
      newObj.userData.active = true;
      this.pool.push(newObj);
      this.activeList.push(newObj);
      return newObj;
    }

    // At capacity, return null (caller should handle gracefully)
    return null;
  }

  release(obj: T): void {
    obj.visible = false;
    obj.userData.active = false;
    const idx = this.activeList.indexOf(obj);
    if (idx !== -1) {
      this.activeList.splice(idx, 1);
    }
  }

  updateActiveState(obj: THREE.Object3D, active: boolean): void {
    obj.visible = active;
    obj.userData.active = active;
  }

  getActiveObjects(): T[] {
    return [...this.activeList];
  }

  getPoolSize(): number {
    return this.pool.length;
  }

  disposeAll(): void {
    for (const obj of this.pool) {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach(m => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    }
    this.pool = [];
    this.activeList = [];
  }
}

import * as THREE from 'three';
import { ObjectPool } from './ObjectPool.js';

export interface ProjectileData {
  velocity: THREE.Vector3;
  isPlayerProjectile: boolean;
  damage: number;
}

const MAX_PROJECTILES = 200;

function createProjectileMesh(): THREE.Mesh {
  const geometry = new THREE.BoxGeometry(0.08, 0.08, 0.4);
  const material = new THREE.MeshStandardMaterial({
    color: 0x00ffff,
    emissive: 0x00ffff,
    emissiveIntensity: 2.0,
    transparent: true,
    opacity: 0.9,
  });
  const mesh = new THREE.Mesh(geometry, material);
  return mesh;
}

export class ProjectilePool {
  private pool: ObjectPool<THREE.Mesh>;
  private projectiles: ProjectileData[] = [];

  constructor(scene: THREE.Scene) {
    this.pool = new ObjectPool<THREE.Mesh>(createProjectileMesh, MAX_PROJECTILES);
    scene.add(this.pool.getActiveObjects()[0] || new THREE.Group());
  }

  acquire(position: THREE.Vector3, velocity: THREE.Vector3, isPlayer: boolean, damage: number = 1): THREE.Mesh | null {
    const obj = this.pool.acquire();
    if (!obj) return null;

    obj.position.copy(position);
    obj.userData.velocity = velocity.clone();
    (obj.userData as any).isPlayerProjectile = isPlayer;
    (obj.userData as any).damage = damage;

    if (isPlayer) {
      obj.material.color.set(0x00ffff);
      obj.material.emissive.set(0x00ffff);
      obj.rotation.z = 0;
    } else {
      obj.material.color.set(0xff3366);
      obj.material.emissive.set(0xff3366);
      obj.rotation.z = Math.PI;
    }

    this.projectiles.push({
      velocity: velocity.clone(),
      isPlayerProjectile: isPlayer,
      damage,
    });

    return obj;
  }

  release(obj: THREE.Mesh): void {
    const idx = this.projectiles.findIndex(
      (p) => p === (obj.userData as any)._projectileRef
    );
    if (idx !== -1) {
      this.projectiles.splice(idx, 1);
    }
    this.pool.release(obj);
  }

  update(dt: number): void {
    const active = this.pool.getActiveObjects();
    for (const obj of active) {
      const vel = (obj.userData as any).velocity;
      if (vel) {
        obj.position.x += vel.x * dt;
        obj.position.y += vel.y * dt;
      }
    }
  }

  getActiveObjects(): THREE.Mesh[] {
    return this.pool.getActiveObjects();
  }

  dispose(): void {
    const active = this.pool.getActiveObjects();
    for (const obj of active) {
      this.pool.release(obj);
    }
    this.projectiles = [];
  }
}

