export class EntityPool {
  private invaderPool: ObjectPool<THREE.Mesh>;
  private playerMeshes: THREE.Group[] = [];
  private ufoPool: ObjectPool<THREE.Mesh>;
  private scene: THREE.Scene;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.invaderPool = new ObjectPool<THREE.Mesh>(() => createInvaderMesh(2), MAX_ENTITIES);
    this.ufoPool = new ObjectPool<THREE.Mesh>(() => createUFOMesh(), 3);
  }

  acquireInvader(type: number): THREE.Mesh | null {
    const mesh = this.invaderPool.acquire();
    if (!mesh) return null;

    // Update geometry based on type
    let newGeometry: THREE.BufferGeometry;
    switch (type) {
      case 0:
        newGeometry = new THREE.IcosahedronGeometry(0.25, 0);
        break;
      case 1:
        newGeometry = new THREE.OctahedronGeometry(0.25, 0);
        break;
      default:
        newGeometry = new THREE.DodecahedGeometry(0.25, 0);
    }

    if (mesh.geometry) mesh.geometry.dispose();
    mesh.geometry = newGeometry;

    const colors = [0x00ff88, 0x00ccff, 0xff66aa];
    const emissives = [0x00ff88, 0x00ccff, 0xff66aa];
    mesh.material.color.set(colors[type] || 0x00ff88);
    (mesh.material as THREE.MeshStandardMaterial).emissive.set(emissives[type] || 0x00ff88);

    return mesh;
  }

  acquirePlayer(): THREE.Group | null {
    const group = new THREE.Group();
    const bodyGeo = new THREE.BoxGeometry(0.5, 0.15, 0.3);
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x004466,
      emissiveIntensity: 0.8,
      roughness: 0.2,
      metalness: 0.8,
    });

    const body = new THREE.Mesh(bodyGeo, bodyMat);
    const cannonGeo = new THREE.BoxGeometry(0.06, 0.06, 0.25);
    const cannon = new THREE.Mesh(cannonGeo, bodyMat.clone());
    cannon.position.z = -0.2;
    cannon.position.y = 0.04;

    const wingGeo = new THREE.BoxGeometry(0.15, 0.08, 0.15);
    const leftWing = new THREE.Mesh(wingGeo, bodyMat.clone());
    leftWing.position.set(-0.3, -0.04, 0.05);
    const rightWing = new THREE.Mesh(wingGeo, bodyMat.clone());
    rightWing.position.set(0.3, -0.04, 0.05);

    group.add(body);
    group.add(cannon);
    group.add(leftWing);
    group.add(rightWing);

    return group;
  }

  acquireUFO(): THREE.Mesh | null {
    return this.ufoPool.acquire();
  }

  releaseInvader(mesh: THREE.Mesh): void {
    if (mesh.geometry) mesh.geometry.dispose();
    this.invaderPool.release(mesh);
  }

  releaseUFO(mesh: THREE.Mesh): void {
    this.ufoPool.release(mesh);
  }

  dispose(): void {
    this.invaderPool.disposeAll();
    this.ufoPool.disposeAll();
  }
}

