function createPlayerGroup(): THREE.Group {
  const group = new THREE.Group();

  // Main body - wedge shape using merged boxes
  const bodyGeo = new THREE.BoxGeometry(0.5, 0.15, 0.3);
  const bodyMat = new THREE.MeshStandardMaterial({
