export class EntityPool {
  private invaderGeometries: Map<number, InvaderGeometrySet> = new Map();
  private playerGroupTemplate: THREE.Group | null = null;
  private ufoMeshes: THREE.Mesh[] = [];
  private scene: THREE.Scene;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    // Pre-create geometry sets for each invader type
    for (let t = 0; t < 3; t++) {
      const set = createInvaderGeometry(t);
      this.invaderGeometries.set(t, set);
    }
    // Pre-create player group template
    this.playerGroupTemplate = createPlayerGroup();
    // Pre-create UFO meshes for pooling
    for (let i = 0; i < MAX_UFOS; i++) {
      const ufo = createUFOMesh();
      ufo.visible = false;
      this.ufoMeshes.push(ufo);
      scene.add(ufo);
    }
  }

  acquireInvader(type: number, position: THREE.Vector3): THREE.Mesh | null {
    const geoSet = this.invaderGeometries.get(type);
    if (!geoSet) return null;

    // Clone material so each invader can have unique emissive animation
    const mat = geoSet.mat.clone();
    const mesh = new THREE.Mesh(geoSet.geo.clone(), mat);
    mesh.position.copy(position);
    mesh.visible = true;
    this.scene.add(mesh);
    return mesh;
  }

  acquirePlayer(): THREE.Group | null {
    if (!this.playerGroupTemplate) return null;
    const clone = this.playerGroupTemplate.clone(true);
    clone.visible = true;
    this.scene.add(clone);
    return clone;
  }

  acquireUFO(position: THREE.Vector3): THREE.Mesh | null {
    for (const ufo of this.ufoMeshes) {
      if (!ufo.userData.active) {
        ufo.position.copy(position);
        ufo.visible = true;
        ufo.userData.active = true;
        return ufo;
      }
    }
    return null;
  }

  releaseInvader(mesh: THREE.Mesh): void {
    if (mesh.geometry) mesh.geometry.dispose();
    if (mesh.material) (mesh.material as THREE.Material).dispose();
    this.scene.remove(mesh);
    mesh.userData.active = false;
  }

  releasePlayer(group: THREE.Group): void {
    group.traverse((child) => {
      if ((child as THREE.Mesh).geometry) (child as THREE.Mesh).geometry.dispose();
      if ((child as THREE.Mesh).material) (child as THREE.Mesh).material.dispose();
    });
    this.scene.remove(group);
  }

  releaseUFO(mesh: THREE.Mesh): void {
    mesh.visible = false;
    mesh.userData.active = false;
  }

  dispose(): void {
    for (const geoSet of this.invaderGeometries.values()) {
      geoSet.geo.dispose();
      geoSet.mat.dispose();
    }
    if (this.playerGroupTemplate) {
      this.playerGroupTemplate.traverse((child) => {
        if ((child as THREE.Mesh).geometry) (child as THREE.Mesh).geometry.dispose();
        if ((child as THREE.Mesh).material) (child as THREE.Mesh).material.dispose();
      });
    }
    for (const ufo of this.ufoMeshes) {
      ufo.geometry.dispose();
      ufo.material.dispose();
      this.scene.remove(ufo);
    }
  }
}

import * as THREE from 'three';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';

// CRT Scanline + Chromatic Aberration shader
const ScanlineShader = {
  uniforms: {
    tDiffuse: { value: null },
    time: { value: 0 },
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float time;
    varying vec2 vUv;

    void main() {
      vec2 uv = vUv;

      // Scanlines
      float scanline = sin(uv.y * 800.0) * 0.04;

      // Chromatic aberration at edges
      float dist = distance(uv, vec2(0.5));
      float caStrength = max(0.0, (dist - 0.3) * 0.5);
      vec2 caOffset = vec2(caStrength * 0.003, 0.0);

      float r = texture2D(tDiffuse, uv + caOffset).r;
      float g = texture2D(tDiffuse, uv).g;
      float b = texture2D(tDiffuse, uv - caOffset).b;

      vec3 color = vec3(r, g, b);
      color -= scanline;

      // Vignette
      float vignette = 1.0 - dist * 0.8;
      color *= vignette;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
};

export class PostProcessingStack {
  private composer: EffectComposer | null = null;
  private bloomPass: UnrealBloomPass | null = null;
  private scanlinePass: ShaderPass | null = null;
  private renderer: THREE.WebGLRenderer;
  private scene: THREE.Scene;
  private camera: THREE.Camera;

  constructor(renderer: THREE.WebGLRenderer, scene: THREE.Scene, camera: THREE.Camera) {
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.init();
  }

  private init(): void {
    this.composer = new EffectComposer(this.renderer);

    // Render pass
    const renderPass = new RenderPass(this.scene, this.camera);
    this.composer.addPass(renderPass);

    // Bloom pass - tuned for neon retro-futurism
    this.bloomPass = new UnrealBloomPass(
      new THREE.Vector2(this.renderer.domElement.width, this.renderer.domElement.height),
      1.2,   // strength
      0.5,   // radius
      0.2    // threshold
    );
    this.composer.addPass(this.bloomPass);

    // Scanline + chromatic aberration pass
    this.scanlinePass = new ShaderPass(ScanlineShader);
    this.composer.addPass(this.scanlinePass);
  }

  update(time: number): void {
    if (this.scanlinePass) {
      (this.scanlinePass.uniforms as any).time.value = time;
    }
  }

  render(): void {
    if (this.composer) {
      this.composer.render();
    }
  }

  setSize(width: number, height: number): void {
    if (this.composer) {
      this.composer.setSize(width, height);
    }
    if (this.bloomPass) {
      this.bloomPass.resolution.set(width, height);
    }
  }

  dispose(): void {
    if (this.composer) {
      this.composer.dispose();
      this.composer = null;
    }
    this.bloomPass = null;
    this.scanlinePass = null;
  }
}

import * as THREE from 'three';

export class GeometryFactory {
  static createGridFloor(width: number, height: number, divisions: number): THREE.Mesh {
    const geometry = new THREE.PlaneGeometry(width, height, divisions, divisions);

    // Add subtle vertex displacement for retro-futurism feel
    const pos = geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const y = pos.getY(i);
      const z = Math.sin(x * 0.5) * Math.cos(y * 0.5) * 0.02;
      pos.setZ(i, z);
    }
    geometry.computeVertexNormals();

    // Create grid texture via canvas
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 256;
    const ctx = canvas.getContext('2d')!;

    // Background
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, 256, 256);

    // Grid lines
    ctx.strokeStyle = 'rgba(0, 255, 255, 0.3)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 256; i += 32) {
      ctx.beginPath();
      ctx.moveTo(i, 0);
      ctx.lineTo(i, 256);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i);
      ctx.lineTo(256, i);
      ctx.stroke();
    }

    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(width / 10, height / 10);

    const material = new THREE.MeshStandardMaterial({
      map: texture,
      emissive: 0x0a0a2a,
      emissiveIntensity: 0.5,
      roughness: 0.8,
      metalness: 0.2,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.y = -1.5;
    return mesh;
  }

  static createStarfield(count: number): THREE.InstancedMesh {
    const geometry = new THREE.OctahedronGeometry(0.02, 0);
    const material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0x4444aa,
      emissiveIntensity: 0.5,
    });

    const instancedMesh = new THREE.InstancedMesh(geometry, material, count);
    const dummy = new THREE.Object3D();

    for (let i = 0; i < count; i++) {
      dummy.position.set(
        (Math.random() - 0.5) * 100,
        (Math.random() - 0.5) * 60 + 20,
        -20 - Math.random() * 80
      );
      dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
      const scale = 0.5 + Math.random() * 1.5;
      dummy.scale.set(scale, scale, scale);
      dummy.updateMatrix();
      instancedMesh.setMatrixAt(i, dummy.matrix);
    }

    return instancedMesh;
  }

  static createShieldBarrier(x: number, y: number): THREE.Group {
    const group = new THREE.Group();
    const voxelSize = 0.08;
    const barrierWidth = 9;
    const barrierHeight = 5;

    const material = new THREE.MeshStandardMaterial({
      color: 0x00ff88,
      emissive: 0x003322,
      emissiveIntensity: 0.5,
      transparent: true,
      opacity: 0.7,
    });

    for (let row = 0; row < barrierHeight; row++) {
      for (let col = 0; col < barrierWidth; col++) {
        // Create arch shape
        const centerX = barrierWidth / 2;
        if (row >= 3 && Math.abs(col - centerX) <= 1) continue;

        const voxel = new THREE.Mesh(
          new THREE.BoxGeometry(voxelSize, voxelSize, voxelSize),
          material.clone()
        );
        voxel.position.set(
          col * voxelSize - (barrierWidth * voxelSize) / 2,
          row * voxelSize - (barrierHeight * voxelSize) / 2,
          0
        );
        group.add(voxel);
      }
    }

    group.position.set(x, y, 0.1);
    return group;
  }

  static disposeGroup(group: THREE.Group): void {
    group.traverse((child) => {
      if ((child as THREE.Mesh).geometry) (child as THREE.Mesh).geometry.dispose();
      if ((child as THREE.Mesh).material) {
        const mat = (child as THREE.Mesh).material;
        if (Array.isArray(mat)) {
          mat.forEach(m => m.dispose());
        } else {
          mat.dispose();
        }
      }
    });
  }
}

// Simplex-like noise using layered sine waves for procedural generation
export class Noise {
  private static seed: number = 42;

  static setSeed(seed: number): void {
    this.seed = seed;
  }

  static hash(x: number, y: number): number {
    let h = this.seed + x * 374761393 + y * 668265263;
    h = (h ^ (h >> 13)) * 1274126177;
    return (h ^ (h >> 16)) / 2147483648.0;
  }

  static smoothNoise(x: number, y: number): number {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const fx = x - ix;
    const fy = y - iy;

    const v1 = this.hash(ix, iy);
    const v2 = this.hash(ix + 1, iy);
    const v3 = this.hash(ix, iy + 1);
    const v4 = this.hash(ix + 1, iy + 1);

    const i1 = v1 * (1 - fx) + v2 * fx;
    const i2 = v3 * (1 - fx) + v4 * fx;
    return i1 * (1 - fy) + i2 * fy;
  }

  static octaveNoise(x: number, y: number, octaves: number, persistence: number): number {
    let total = 0;
    let frequency = 1;
    let amplitude = 1;
    let maxValue = 0;

    for (let i = 0; i < octaves; i++) {
      total += this.smoothNoise(x * frequency, y * frequency) * amplitude;
      maxValue += amplitude;
      amplitude *= persistence;
      frequency *= 2;
    }

    return total / maxValue;
  }

  static displacement(value: number, scale: number): number {
    return Math.sin(value * scale) * 0.1 + Math.cos(value * scale * 0.7) * 0.05;
  }
}

export class Timer {
  private elapsed: number = 0;
  private running: boolean = false;

  get time(): number { return this.elapsed; }
  get isRunning(): boolean { return this.running; }

  start(): void {
    if (!this.running) {
      this.startTime = performance.now();
      this.running = true;
    }
  }

  stop(): void {
    if (this.running) {
      this.elapsed += performance.now() - this.startTime;
      this.running = false;
    }
  }

  reset(): void {
    this.elapsed = 0;
    this.running = false;
  }

  private startTime: number = 0;
}

export class CooldownTracker {
  private cooldowns: Map<string, number> = new Map();

  addCooldown(name: string, duration: number): void {
    this.cooldowns.set(name, performance.now() + duration * 1000);
  }

  canAct(name: string): boolean {
    const end = this.cooldowns.get(name);
    if (end === undefined) return true;
    if (performance.now() >= end) {
      this.cooldowns.delete(name);
      return true;
    }
    return false;
  }

  resetCooldown(name: string): void {
    this.cooldowns.delete(name);
  }
}

