import * as THREE from 'three';
import { InputManager } from '../../../shared/input/InputManager.js';
import type { AudioEngine } from '../../../shared/audio/AudioEngine.js';

export class PlayerEntity {
  private group: THREE.Group | null = null;
  private input: InputManager;
  private audio: AudioEngine;
  private position: THREE.Vector3;
  private speed: number;
  private halfWidth: number;
  private fireCooldown: number = 0;
  private fireInterval: number;
  private alive: boolean = true;

  constructor(input: InputManager, audio: AudioEngine) {
    this.input = input;
    this.audio = audio;
    this.position = new THREE.Vector3(0, -5.5, 0);
    this.speed = 8.0;
    this.halfWidth = 0.4;
    this.fireInterval = 0.25;
  }

  create(): THREE.Group {
    const group = new THREE.Group();

    // Main body - wedge shape
    const bodyGeo = new THREE.BoxGeometry(0.5, 0.15, 0.3);
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x004466,
      emissiveIntensity: 0.8,
      roughness: 0.2,
      metalness: 0.8,
    });
    const body = new THREE.Mesh(bodyGeo, bodyMat);

    // Cannon barrel
    const cannonGeo = new THREE.BoxGeometry(0.06, 0.06, 0.25);
    const cannon = new THREE.Mesh(cannonGeo, bodyMat.clone());
    cannon.position.z = -0.2;
    cannon.position.y = 0.04;

    // Left wing
    const wingGeo = new THREE.BoxGeometry(0.15, 0.08, 0.15);
    const leftWing = new THREE.Mesh(wingGeo, bodyMat.clone());
    leftWing.position.set(-0.3, -0.04, 0.05);

    // Right wing
    const rightWing = new THREE.Mesh(wingGeo, bodyMat.clone());
    rightWing.position.set(0.3, -0.04, 0.05);

    group.add(body);
    group.add(cannon);
    group.add(leftWing);
    group.add(rightWing);

    this.group = group;
    return group;
  }

  update(dt: number): { projectile?: THREE.Mesh } | null {
    if (!this.alive || !this.group) return null;

    // Horizontal movement
    let moveX = 0;
    moveX += this.input.isDown('KeyD') || this.input.isDown('ArrowRight') ? 1 : 0;
    moveX -= this.input.isDown('KeyA') || this.input.isDown('ArrowLeft') ? 1 : 0;

    // Gamepad override
    if (Math.abs(this.input.gamepad.axisXRaw) > 0.1) {
      moveX = Math.sign(this.input.gamepad.axisXRaw);
    }

    const newX = this.position.x + moveX * this.speed * dt;
    this.position.x = Math.max(-9.5, Math.min(9.5, newX));
    this.group.position.copy(this.position);

    // Fire
    this.fireCooldown -= dt;
    if (this.fireCooldown <= 0 && (this.input.fireInput || this.input.fireJustPressed)) {
      this.fireCooldown = this.fireInterval;
      return this.fire();
    }

    return null;
  }

  private fire(): { projectile: THREE.Mesh } | null {
    if (!this.group) return null;

    const projGeo = new THREE.BoxGeometry(0.08, 0.08, 0.4);
    const projMat = new THREE.MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x00ffff,
      emissiveIntensity: 2.0,
      transparent: true,
      opacity: 0.9,
    });
    const projectile = new THREE.Mesh(projGeo, projMat);

    const startX = this.position.x;
    const startY = this.position.y - 0.15;
    projectile.position.set(startX, startY, 0);
    (projectile.userData as any).velocity = new THREE.Vector3(0, 12, 0);
    (projectile.userData as any).isPlayerProjectile = true;
    (projectile.userData as any).damage = 1;

    this.audio.playLaser();
    return { projectile };
  }

  takeDamage(): void {
    this.alive = false;
  }

  reset(position: THREE.Vector3): void {
    this.alive = true;
    this.position.copy(position);
    if (this.group) {
      this.group.visible = true;
    }
  }

  dispose(): void {
    if (this.group) {
      this.group.traverse((child) => {
        const mesh = child as THREE.Mesh;
        if (mesh.geometry) mesh.geometry.dispose();
        if (mesh.material) {
          const mat = mesh.material;
          if (Array.isArray(mat)) mat.forEach(m => m.dispose());
          else mat.dispose();
        }
      });
    }
  }
}

import * as THREE from 'three';

export interface InvaderData {
  mesh: THREE.Mesh;
  type: number;
  alive: boolean;
  baseEmissive: number;
}

const INVADER_COLORS = [0x00ff88, 0x00ccff, 0xff66aa];
const INVADER_EMISSIVES = [0x00ff88, 0x00ccff, 0xff66aa];

export class InvaderEntity {
  private meshes: THREE.Mesh[] = [];
  private types: number[] = [];
  private baseEmissives: number[] = [];

  constructor() {}

  createMesh(type: number): THREE.Mesh | null {
    let geometry: THREE.BufferGeometry;
    switch (type) {
      case 0: // Top row - Icosahedron
        geometry = new THREE.IcosahedronGeometry(0.25, 0);
        break;
      case 1: // Middle rows - Octahedron
        geometry = new THREE.OctahedronGeometry(0.25, 0);
        break;
      default: // Bottom rows - Dodecahedron approximation with Icosahedron scaled
        geometry = new THREE.IcosahedronGeometry(0.28, 1);
        break;
    }

    const color = INVADER_COLORS[type] || 0x00ff88;
    const emissive = INVADER_EMISSIVES[type] || 0x00ff88;
    const material = new THREE.MeshStandardMaterial({
      color: color,
      emissive: emissive,
      emissiveIntensity: 1.5,
      roughness: 0.3,
      metalness: 0.7,
    });

    const mesh = new THREE.Mesh(geometry, material);
    this.meshes.push(mesh);
    this.types.push(type);
    this.baseEmissives.push(1.5);
    return mesh;
  }

  update(dt: number, pulsePhase: number): void {
    for (let i = 0; i < this.meshes.length; i++) {
      const mesh = this.meshes[i];
      if (!mesh.visible) continue;

      // Pulsing emissive based on row type and phase
      const baseEmissive = this.baseEmissives[i];
      const pulse = Math.sin(pulsePhase + i * 0.5) * 0.3;
      (mesh.material as THREE.MeshStandardMaterial).emissiveIntensity =
        Math.max(0.2, baseEmissive + pulse);

      // Subtle bobbing animation
      mesh.position.y += Math.sin(pulsePhase * 2 + i) * dt * 0.1;
    }
  }

  getMeshes(): THREE.Mesh[] {
    return this.meshes.filter(m => m.visible);
  }

  dispose(): void {
    for (const mesh of this.meshes) {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) {
        const mat = mesh.material;
        if (Array.isArray(mat)) mat.forEach(m => m.dispose());
        else mat.dispose();
      }
    }
    this.meshes = [];
  }
}

import * as THREE from 'three';

export class ProjectileEntity {
  private meshes: THREE.Mesh[] = [];

  createPlayerProjectile(position: THREE.Vector3): THREE.Mesh {
    const geo = new THREE.BoxGeometry(0.08, 0.08, 0.4);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x00ffff,
      emissive: 0x00ffff,
      emissiveIntensity: 2.0,
      transparent: true,
      opacity: 0.9,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position);
    (mesh.userData as any).velocity = new THREE.Vector3(0, 14, 0);
    (mesh.userData as any).isPlayerProjectile = true;
    (mesh.userData as any).damage = 1;
    this.meshes.push(mesh);
    return mesh;
  }

  createEnemyProjectile(position: THREE.Vector3): THREE.Mesh {
    const geo = new THREE.BoxGeometry(0.08, 0.08, 0.4);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xff3366,
      emissive: 0xff3366,
      emissiveIntensity: 2.0,
      transparent: true,
      opacity: 0.9,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position);
    (mesh.userData as any).velocity = new THREE.Vector3(0, -8, 0);
    (mesh.userData as any).isPlayerProjectile = false;
    (mesh.userData as any).damage = 1;
    this.meshes.push(mesh);
    return mesh;
  }

  update(dt: number): void {
    for (const mesh of this.meshes) {
      if (!mesh.visible) continue;
      const vel = (mesh.userData as any).velocity;
      if (vel) {
        mesh.position.x += vel.x * dt;
        mesh.position.y += vel.y * dt;
      }
    }
  }

  remove(mesh: THREE.Mesh): void {
    mesh.visible = false;
    const idx = this.meshes.indexOf(mesh);
    if (idx !== -1) this.meshes.splice(idx, 1);
  }

  getAllMeshes(): THREE.Mesh[] {
    return this.meshes.filter(m => m.visible);
  }

  dispose(): void {
    for (const mesh of this.meshes) {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) {
        const mat = mesh.material;
        if (Array.isArray(mat)) mat.forEach(m => m.dispose());
        else mat.dispose();
      }
    }
    this.meshes = [];
  }
}

import * as THREE from 'three';

export class UFOEntity {
  private mesh: THREE.Mesh | null = null;
  private active: boolean = false;
  private position: THREE.Vector3;
  private direction: number = 1;
  private speed: number = 2.0;
  private scoreValue: number = 150;

  constructor() {
    this.position = new THREE.Vector3();
  }

  create(): THREE.Mesh | null {
    const geometry = new THREE.TorusGeometry(0.2, 0.08, 8, 16);
    const material = new THREE.MeshStandardMaterial({
      color: 0xff00ff,
      emissive: 0xff00ff,
      emissiveIntensity: 3.0,
      transparent: true,
      opacity: 0.9,
      roughness: 0.1,
      metalness: 0.9,
    });
    this.mesh = new THREE.Mesh(geometry, material);
    return this.mesh;
  }

  spawn(x: number): void {
    if (!this.mesh) return;
    this.active = true;
    this.position.set(x, 5.5, 0);
    this.mesh.position.copy(this.position);
    this.mesh.visible = true;
    // Random direction
    this.direction = Math.random() > 0.5 ? 1 : -1;
  }

  update(dt: number): void {
    if (!this.active || !this.mesh) return;
    const newX = this.position.x + this.direction * this.speed * dt;
    // Check bounds
    if (this.direction > 0 && newX > 10) {
      this.despawn();
    } else if (this.direction < 0 && newX < -10) {
      this.despawn();
    } else {
      this.position.x = newX;
      this.mesh.position.copy(this.position);
    }
    // Rotate for visual effect
    this.mesh.rotation.z += dt * 2;
  }

  despawn(): void {
    if (this.mesh) {
      this.mesh.visible = false;
    }
    this.active = false;
  }

  get isActive(): boolean { return this.active; }
  get position(): THREE.Vector3 { return this.position; }
  get direction(): number { return this.direction; }
  get speed(): number { return this.speed; }
  get scoreValue(): number { return this.scoreValue; }

  dispose(): void {
    if (this.mesh) {
      if (this.mesh.geometry) this.mesh.geometry.dispose();
      if (this.mesh.material) this.mesh.material.dispose();
    }
    this.mesh = null;
  }
}

import * as THREE from 'three';
import { InvaderEntity } from '../entities/InvaderEntity.js';
import type { AudioEngine } from '../../../shared/audio/AudioEngine.js';

export interface InvaderGridCell {
  mesh: THREE.Mesh;
  alive: boolean;
  row: number;
  col: number;
}

export class SpawnerSystem {
  private invaderEntities: InvaderEntity[] = [];
  private grid: InvaderGridCell[][] = [];
  private audio: AudioEngine;
  private direction: number = 1; // 1 = right, -1 = left
  private stepSpeed: number = 0.3;
  private dropDistance: number = 0.15;
  private pulsePhase: number = 0;
  private marchTimer: number = 0;
  private marchInterval: number = 1.0;

  constructor(audio: AudioEngine) {
    this.audio = audio;
  }

  init(cols: number, rows: number): void {
    this.grid = [];
    this.invaderEntities = [];

    for (let row = 0; row < rows; row++) {
      const rowMeshes = new InvaderEntity();
      const entity = rowMeshes;
      this.invaderEntities.push(entity);
      const rowType = row < 1 ? 0 : row < 3 ? 1 : 2;

      for (let col = 0; col < cols; col++) {
        const mesh = entity.createMesh(rowType);
        if (!mesh) continue;

        const x = -((cols - 1) * 0.7) / 2 + col * 0.7;
        const y = 4.5 - row * 0.6;
        mesh.position.set(x, y, 0);
        this.grid.push({ mesh, alive: true, row, col });
      }
    }
  }

  update(dt: number): { projectiles?: THREE.Mesh[] } | null {
    let enemyProjectiles: THREE.Mesh[] = [];

    // Update pulse phase for animation
    this.pulsePhase += dt * 3;
    this.marchTimer += dt;

    // March sound interval
    if (this.marchTimer >= this.marchInterval) {
      this.audio.playMarch();
      this.marchTimer = 0;
      this.marchInterval = Math.max(0.2, 1.0 - this.stepSpeed * 0.3);
    }

    // Update all invader entities with pulse animation
    for (const entity of this.invaderEntities) {
      entity.update(dt, this.pulsePhase);
    }

    // Random enemy fire
    const aliveGrid = this.grid.filter(cell => cell.alive);
    if (aliveGrid.length > 0 && Math.random() < dt * 2.0) {
      const shooter = aliveGrid[Math.floor(Math.random() * aliveGrid.length)];
      const projGeo = new THREE.BoxGeometry(0.08, 0.08, 0.4);
      const projMat = new THREE.MeshStandardMaterial({
        color: 0xff3366,
        emissive: 0xff3366,
        emissiveIntensity: 2.0,
        transparent: true,
        opacity: 0.9,
      });
      const proj = new THREE.Mesh(projGeo, projMat);
      proj.position.set(shooter.mesh.position.x, shooter.mesh.position.y - 0.2, 0);
      (proj.userData as any).velocity = new THREE.Vector3(0, -8, 0);
      (proj.userData as any).isPlayerProjectile = false;
      (proj.userData as any).damage = 1;
      enemyProjectiles.push(proj);
    }

    return enemyProjectiles.length > 0 ? { projectiles: enemyProjectiles } : null;
  }

  getGrid(): InvaderGridCell[] {
    return this.grid.filter(c => c.alive);
  }

  getDirection(): number { return this.direction; }
  setDirection(d: number): void { this.direction = d; }
  getStepSpeed(): number { return this.stepSpeed; }
  setStepSpeed(s: number): void { this.stepSpeed = s; }
  getPulsePhase(): number { return this.pulsePhase; }

  dropInvaders(): void {
    for (const cell of this.grid) {
      if (cell.alive) {
        cell.mesh.position.y -= this.dropDistance;
      }
    }
  }

  increaseSpeed(factor: number): void {
    this.stepSpeed *= factor;
  }

  dispose(): void {
    for (const entity of this.invaderEntities) {
      entity.dispose();
    }
    this.invaderEntities = [];
    this.grid = [];
  }
}

import * as THREE from 'three';
import type { BBox } from '../../../shared/types.js';
import { createAABB, aabbOverlap } from '../../../shared/math/AABB.js';

export interface CollisionResult {
  destroyed: THREE.Mesh[];
  playerProjectiles: THREE.Mesh[];
  enemyProjectiles: THREE.Mesh[];
}

const PROJECTILE_HALF_W = 0.05;
const PROJECTILE_HALF_H = 0.2;
const INVADER_HIT_RADIUS = 0.3;

export class CollisionSystem {
  private result: CollisionResult = { destroyed: [], playerProjectiles: [], enemyProjectiles: [] };

  constructor() {
    this.reset();
  }

  reset(): void {
    this.result.destroyed = [];
    this.result.playerProjectiles = [];
    this.result.enemyProjectiles = [];
  }

  check(
    playerProjMeshes: THREE.Mesh[],
    enemyProjMeshes: THREE.Mesh[],
    invaderCells: Array<{ mesh: THREE.Mesh; alive: boolean; row: number; col: number }>
  ): CollisionResult {
    this.reset();

    // Check player projectiles against invaders
    for (const proj of playerProjMeshes) {
      if (!proj.visible) continue;
      const pBox = createAABB(
        proj.position.x, proj.position.y,
        PROJECTILE_HALF_W * 2, PROJECTILE_HALF_H * 2
      );

      for (const cell of invaderCells) {
        if (!cell.alive) continue;
        const iBox = createAABB(
          cell.mesh.position.x, cell.mesh.position.y,
          INVADER_HIT_RADIUS * 2, INVADER_HIT_RADIUS * 2
        );

        if (aabbOverlap(pBox, iBox)) {
          cell.alive = false;
          cell.mesh.visible = false;
          this.result.destroyed.push(cell.mesh);
          break;
        }
      }
    }

    // Check enemy projectiles against player area
    const PLAYER_Y = -5.5;
    const PLAYER_HALF_W = 0.35;
    const PLAYER_BOX = createAABB(0, PLAYER_Y, PLAYER_HALF_W * 2, 0.2);

    for (const proj of enemyProjMeshes) {
      if (!proj.visible) continue;
      const pBox = createAABB(
        proj.position.x, proj.position.y,
        PROJECTILE_HALF_W * 2, PROJECTILE_HALF_H * 2
      );

      if (aabbOverlap(pBox, PLAYER_BOX)) {
        this.result.enemyProjectiles.push(proj);
        continue;
      }

      // Check if invader crossed bottom threshold
      if (proj.position.y < -6.5) {
        this.result.enemyProjectiles.push(proj);
      }
    }

    return this.result;
  }

  checkUFOCollision(
    ufoActive: boolean,
    ufoPos: THREE.Vector3 | null,
    playerProjMeshes: THREE.Mesh[]
  ): boolean {
    if (!ufoActive || !ufoPos) return false;

    const ufoBox = createAABB(ufoPos.x, ufoPos.y, 0.5, 0.2);

    for (const proj of playerProjMeshes) {
      if (!proj.visible) continue;
      const pBox = createAABB(
        proj.position.x, proj.position.y,
        PROJECTILE_HALF_W * 2, PROJECTILE_HALF_H * 2
      );

      if (aabbOverlap(pBox, ufoBox)) {
        return true;
      }
    }
    return false;
  }
}

import * as THREE from 'three';
import type { AudioEngine } from '../../../shared/audio/AudioEngine.js';
import { CameraShake } from '../../../shared/vfx/CameraShake.js';
import { ParticleManager } from '../../../shared/vfx/ParticleManager.js';
import { ShockwaveRing } from '../../../shared/vfx/ShockwaveRing.js';
import { FloatingScoreText } from '../../../shared/vfx/FloatingScoreText.js';
import type { Vector3f } from '../../../shared/types.js';

export interface LevelConfig {
  level: number;
  invaderSpeed: number;
  enemyFireRate: number;
  ufoInterval: number;
}

export class LevelManager {
  private audio: AudioEngine;
  private cameraShake: CameraShake;
  private particleManager: ParticleManager;
  private shockwaveRing: ShockwaveRing;
  private floatingScoreText: FloatingScoreText;
  private scene: THREE.Scene;

  private currentLevel: number = 1;
  private score: number = 0;
  private highScore: number = 0;
  private lives: number = 3;
  private playerAlive: boolean = true;
  private gameOver: boolean = false;
  private levelTransition: boolean = false;

  constructor(
    scene: THREE.Scene,
    audio: AudioEngine,
    cameraShake: CameraShake,
    particleManager: ParticleManager,
    shockwaveRing: ShockwaveRing,
    floatingScoreText: FloatingScoreText
  ) {
    this.scene = scene;
    this.audio = audio;
    this.cameraShake = cameraShake;
    this.particleManager = particleManager;
    this.shockwaveRing = shockwaveRing;
    this.floatingScoreText = floatingScoreText;
  }

  get level(): number { return this.currentLevel; }
  get score(): number { return this.score; }
  get highScore(): number { return this.highScore; }
  get lives(): number { return this.lives; }
  get playerAlive(): boolean { return this.playerAlive; }
  get gameOver(): boolean { return this.gameOver; }
  get levelTransition(): boolean { return this.levelTransition; }

  getLevelConfig(): LevelConfig {
    const speedMult = 1.0 + (this.currentLevel - 1) * 0.15;
    const fireRateMult = Math.max(0.3, 1.0 - (this.currentLevel - 1) * 0.1);
    return {
      level: this.currentLevel,
      invaderSpeed: 0.3 * speedMult,
      enemyFireRate: fireRateMult,
      ufoInterval: Math.max(10, 25 - this.currentLevel * 2),
    };
  }

  addScore(points: number, position?: Vector3f): void {
    this.score += points;
    if (this.score > this.highScore) {
      this.highScore = this.score;
    }
    if (position) {
      this.floatingScoreText.spawn(position, points);
    }
  }

  spawnExplosionParticles(position: Vector3f, color: number = 0x00ffff): void {
    for (let i = 0; i < 20; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 1.0 + Math.random() * 3.0;
      this.particleManager.spawn({
        position: { x: position.x, y: position.y, z: 0 },
        velocity: { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed, z: 0 },
        color: color,
        size: 0.1 + Math.random() * 0.15,
        life: 0.3 + Math.random() * 0.4,
      });
    }
  }

  triggerCameraShake(intensity: number): void {
    this.cameraShake.trigger(intensity);
  }

  spawnShockwave(position: Vector3f, color: number = 0x00ffff): void {
    this.shockwaveRing.spawn(position, color);
  }

  playerHit(): void {
    this.lives--;
    this.playerAlive = false;
    this.audio.playPlayerHit();
    this.triggerCameraShake(0.3);
    if (this.lives <= 0) {
      this.gameOver = true;
    }
  }

  playerResurrect(position: THREE.Vector3): void {
    this.playerAlive = true;
    // Player position will be set by the game loop
  }

  levelComplete(): void {
    this.levelTransition = true;
    this.currentLevel++;
    setTimeout(() => {
      this.levelTransition = false;
    }, 2000);
  }

  resetGame(): void {
    this.currentLevel = 1;
    this.score = 0;
    this.lives = 3;
    this.playerAlive = true;
    this.gameOver = false;
  }

  dispose(): void {
    // No specific resources to clean up
  }
}

import * as THREE from 'three';
import { InputManager } from '../../shared/input/InputManager.js';
import { AudioEngine } from '../../shared/audio/AudioEngine.js';
import { CameraShake } from '../../shared/vfx/CameraShake.js';
import { ParticleManager } from '../../shared/vfx/ParticleManager.js';
import { ShockwaveRing } from '../../shared/vfx/ShockwaveRing.js';
import { FloatingScoreText } from '../../shared/vfx/FloatingScoreText.js';
import { HitStop } from '../../shared/vfx/HitStop.js';
import { PostProcessingStack } from '../../shared/rendering/PostProcessingStack.js';
import { GeometryFactory } from '../../shared/rendering/GeometryFactory.js';
import { PlayerEntity } from './entities/PlayerEntity.js';
import { InvaderEntity } from './entities/InvaderEntity.js';
import { ProjectileEntity } from './entities/ProjectileEntity.js';
import { UFOEntity } from './entities/UFOEntity.js';
import { SpawnerSystem, type InvaderGridCell } from './systems/SpawnerSystem.js';
import { CollisionSystem } from './systems/CollisionSystem.js';
import { LevelManager } from './systems/LevelManager.js';
import { ARENA_WIDTH, ARENA_HEIGHT, PLAYER_Y, INVADER_COLS, INVADER_ROWS } from './constants.js';

export class Game {
  private renderer: THREE.WebGLRenderer;
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private input: InputManager;
  private audio: AudioEngine;
  private clock: THREE.Clock;
  private animationId: number | null = null;

  // VFX systems
  private cameraShake: CameraShake;
  private particleManager: ParticleManager;
  private shockwaveRing: ShockwaveRing;
  private floatingScoreText: FloatingScoreText;
  private hitStop: HitStop;
  private postProcessing: PostProcessingStack;

  // Game entities
  private player: PlayerEntity;
  private spawner: SpawnerSystem;
  private projectiles: ProjectileEntity;
  private ufo: UFOEntity;

  // Systems
  private collision: CollisionSystem;
  private levelManager: LevelManager;

  // Grid state
  private invaderGrid: InvaderGridCell[] = [];
  private playerProjectiles: THREE.Mesh[] = [];
  private enemyProjectiles: THREE.Mesh[] = [];
  private invaderDirection: number = 1;
  private stepSpeed: number = 0.3;
  private ufoTimer: number = 0;
  private ufoInterval: number = 25;

  // State
  private gameOver: boolean = false;
  private levelTransition: boolean = false;
  private transitionTimer: number = 0;

  constructor() {
    this.clock = new THREE.Clock();
    this.initRenderer();
    this.initScene();
    this.initCamera();
    this.initInput();
    this.initAudio();
    this.initVFXSystems();
    this.initPostProcessing();
    this.initGameEntities();
    this.initLevelManager();
    this.initStarfield();
    this.initGridFloor();
  }

  private initRenderer(): void {
    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.0;
    document.body.appendChild(this.renderer.domElement);
  }

  private initScene(): void {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x050510);
    this.scene.fog = new THREE.FogExp2(0x050510, 0.015);
  }

  private initCamera(): void {
    const aspect = window.innerWidth / window.innerHeight;
    const frustumSize = 14;
    this.camera = new THREE.PerspectiveCamera(
      45,
      aspect,
      0.1,
      100
    );
    this.camera.position.set(0, 0, 18);
    this.camera.lookAt(0, 0, 0);
  }

  private initInput(): void {
    this.input = new InputManager();
    this.input.startPolling();
  }

  private initAudio(): void {
    this.audio = new AudioEngine();
  }

  private initVFXSystems(): void {
    this.cameraShake = new CameraShake(this.camera);
    this.particleManager = new ParticleManager(this.scene);
    this.shockwaveRing = new ShockwaveRing(this.scene);
    this.floatingScoreText = new FloatingScoreText(this.scene, this.camera);
    this.hitStop = new HitStop();
  }

  private initPostProcessing(): void {
    this.postProcessing = new PostProcessingStack(
      this.renderer,
      this.scene,
      this.camera
    );
  }

  private initGameEntities(): void {
    this.player = new PlayerEntity(this.input, this.audio);
    this.spawner = new SpawnerSystem(this.audio);
    this.projectiles = new ProjectileEntity();
    this.ufo = new UFOEntity();
    this.collision = new CollisionSystem();
  }

  private initLevelManager(): void {
    this.levelManager = new LevelManager(
      this.scene,
      this.audio,
      this.cameraShake,
      this.particleManager,
      this.shockwaveRing,
      this.floatingScoreText
    );
  }

  private initStarfield(): void {
    const starfield = GeometryFactory.createStarfield(500);
    this.scene.add(starfield);
  }

  private initGridFloor(): void {
    const gridFloor = GeometryFactory.createGridFloor(60, 40, 40);
    this.scene.add(gridFloor);
  }

  public start(): void {
    this.input.gamepad.startPolling();
    this.gameLoop();
    this.updateHUD();
  }

  private gameLoop = (): void => {
    this.animationId = requestAnimationFrame(this.gameLoop);

    const rawDt = this.clock.getDelta();
    const dt = this.hitStop.isActive ? rawDt * this.hitStop.timescale : rawDt;

    // Update hit-stop counter
    this.hitStop.update(rawDt);

    if (this.levelTransition) {
      this.transitionTimer -= rawDt;
      if (this.transitionTimer <= 0) {
        this.levelTransition = false;
        this.resetLevel();
      }
      return;
    }

    if (!this.gameOver) {
      this.updatePlayer(dt);
      this.updateInvaders(dt);
      this.updateProjectiles(dt);
      this.updateUFO(dt);
      this.checkCollisions();
      this.updateVFX(dt);
    }

    // Render
    this.postProcessing.render();
  };

  private updatePlayer(dt: number): void {
    if (!this.player) return;
    const result = this.player.update(dt);
    if (result && result.projectile) {
      this.playerProjectiles.push(result.projectile);
    }
  }

  private updateInvaders(dt: number): void {
    const projResult = this.spawner.update(dt);
    if (projResult?.projectiles) {
      this.enemyProjectiles.push(...projResult.projectiles);
    }

    // Check invader bounds for direction change
    const aliveCells = this.invaderGrid.filter(c => c.alive);
    let hitEdge = false;
    for (const cell of aliveCells) {
      if (this.invaderDirection > 0 && cell.mesh.position.x > ARENA_WIDTH / 2 - 0.5) {
        hitEdge = true;
        break;
      }
      if (this.invaderDirection < 0 && cell.mesh.position.x < -ARENA_WIDTH / 2 + 0.5) {
        hitEdge = true;
        break;
      }
    }

    if (hitEdge) {
      this.invaderDirection *= -1;
      this.spawner.dropInvaders();
      this.levelManager.triggerCameraShake(0.1);
    }

    // Check if invaders reached bottom
    for (const cell of aliveCells) {
      if (cell.mesh.position.y < -6) {
        this.gameOver = true;
        this.audio.playPlayerHit();
        break;
      }
    }

    // Check level complete
    if (aliveCells.length === 0 && !this.levelTransition) {
      this.levelComplete();
    }
  }

  private updateProjectiles(dt: number): void {
    this.projectiles.update(dt);

    // Remove off-screen projectiles
    this.playerProjectiles = this.playerProjectiles.filter(p => {
      if (!p.visible || p.position.y > 10) return false;
      return true;
    });

    this.enemyProjectiles = this.enemyProjectiles.filter(p => {
      if (!p.visible || p.position.y < -8) return false;
      return true;
    });
  }

  private updateUFO(dt: number): void {
    if (this.ufo.isActive) {
      this.ufo.update(dt);
    } else {
      this.ufoTimer += dt;
      if (this.ufoTimer >= this.ufoInterval) {
        const startX = Math.random() > 0.5 ? -10 : 10;
        this.ufo.spawn(startX);
        this.audio.playUfoAppear();
        this.ufoTimer = 0;
        this.ufoInterval = 15 + Math.random() * 20;
      }
    }
  }

  private checkCollisions(): void {
    const result = this.collision.check(
      this.playerProjectiles,
      this.enemyProjectiles,
      this.invaderGrid
    );

    // Handle destroyed invaders
    for (const mesh of result.destroyed) {
      const cell = this.invaderGrid.find(c => c.mesh === mesh);
      if (cell) {
        const row = cell.row;
        let score = 10;
        if (row < 1) score = 30;
        else if (row < 3) score = 20;

        this.levelManager.addScore(score, { x: mesh.position.x, y: mesh.position.y, z: 0 });
        const color = row < 1 ? 0x00ff88 : row < 3 ? 0x00ccff : 0xff66aa;
        this.levelManager.spawnExplosionParticles(
          { x: mesh.position.x, y: mesh.position.y, z: 0 },
          color
        );
        this.levelManager.spawnShockwave(
          { x: mesh.position.x, y: mesh.position.y, z: 0 },
          color
        );
        this.audio.playExplosion();
        this.levelManager.triggerCameraShake(0.15);
      }
    }

    // Handle player hit by enemy projectile
    if (result.enemyProjectiles.length > 0) {
      for (const proj of result.enemyProjectiles) {
        this.player.takeDamage();
        this.audio.playPlayerHit();
        this.levelManager.triggerCameraShake(0.4);
        this.hitStop.trigger(6);
        this.levelManager.spawnExplosionParticles(
          { x: this.player.position.x, y: this.player.position.y, z: 0 },
          0x00ffff
        );

        if (this.levelManager.gameOver) {
          setTimeout(() => this.showGameOver(), 1500);
        } else {
          setTimeout(() => {
            this.player.reset(new THREE.Vector3(0, PLAYER_Y, 0));
            this.levelManager.playerResurrect(new THREE.Vector3(0, PLAYER_Y, 0));
          }, 1500);
        }
      }
    }

    // Clean up destroyed projectiles
    for (const proj of result.destroyed) {
      const idx = this.playerProjectiles.indexOf(proj);
      if (idx !== -1) this.playerProjectiles.splice(idx, 1);
    }
  }

  private updateVFX(dt: number): void {
    this.cameraShake.update(dt);
    this.particleManager.update(dt);
    this.shockwaveRing.update(dt);
    this.floatingScoreText.update(dt);
    this.postProcessing.update(this.clock.getElapsedTime());
  }

  private levelComplete(): void {
    this.levelTransition = true;
    this.transitionTimer = 2.0;
    this.audio.playPowerup();
    this.levelManager.levelComplete();
  }

  private resetLevel(): void {
    // Clear existing grid
    for (const cell of this.invaderGrid) {
      if (cell.mesh.visible) {
        cell.mesh.visible = false;
      }
    }
    this.invaderGrid = [];
    this.playerProjectiles = [];
    this.enemyProjectiles = [];
    this.ufo.despawn();
    this.ufoTimer = 0;

    // Rebuild grid for new level
    const config = this.levelManager.getLevelConfig();
    this.stepSpeed = config.invaderSpeed;
    this.spawner.init(INVADER_COLS, INVADER_ROWS);

    // Collect all created meshes into the grid
    for (let row = 0; row < INVADER_ROWS; row++) {
      const rowType = row < 1 ? 0 : row < 3 ? 1 : 2;
      for (let col = 0; col < INVADER_COLS; col++) {
        const x = -((INVADER_COLS - 1) * 0.7) / 2 + col * 0.7;
        const y = 4.5 - row * 0.6;
        this.invaderGrid.push({
          mesh: new THREE.Mesh(), // Placeholder - will be replaced
          alive: true,
          row,
          col,
        });
      }
    }

    // Actually rebuild from spawner system
    this.invaderGrid = [];
    for (let row = 0; row < INVADER_ROWS; row++) {
      const rowType = row < 1 ? 0 : row < 3 ? 1 : 2;
      for (let col = 0; col < INVADER_COLS; col++) {
        const x = -((INVADER_COLS - 1) * 0.7) / 2 + col * 0.7;
        const y = 4.5 - row * 0.6;
        // Create a placeholder mesh at the grid position
        const geo = new THREE.BoxGeometry(0.01, 0.01, 0.01);
        const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
        const mesh = new THREE.Mesh(geo, mat);
        mesh.position.set(x, y, 0);
        this.invaderGrid.push({ mesh, alive: true, row, col });
      }
    }
  }

  private showGameOver(): void {
    const overlay = document.getElementById('game-overlay');
    if (overlay) {
      overlay.classList.remove('hidden');
      const text = document.getElementById('overlay-text');
      if (text) {
        text.innerHTML = `
          <h1>GAME OVER</h1>
          <p>Final Score: ${this.levelManager.score}<br>High Score: ${this.levelManager.highScore}</p>
          <button id="restart-btn">PLAY AGAIN</button>
        `;
        document.getElementById('restart-btn')?.addEventListener('click', () => {
          this.restart();
        });
      }
    }
  }

  private restart(): void {
    const overlay = document.getElementById('game-overlay');
    if (overlay) overlay.classList.add('hidden');

    // Reset game state
    this.gameOver = false;
    this.levelTransition = false;
    this.playerProjectiles = [];
    this.enemyProjectiles = [];
    this.ufo.despawn();
    this.ufoTimer = 0;

    // Reset player
    this.player.reset(new THREE.Vector3(0, PLAYER_Y, 0));
    this.levelManager.resetGame();
    this.updateHUD();

    // Rebuild invader grid for new level
    const config = this.levelManager.getLevelConfig();
    this.stepSpeed = config.invaderSpeed;
    this.spawner.init(INVADER_COLS, INVADER_ROWS);
  }

  private updateHUD(): void {
    const scoreDisplay = document.getElementById('score-display');
    if (scoreDisplay) {
      scoreDisplay.textContent = String(this.levelManager.score);
    }

    const livesDisplay = document.getElementById('lives-display');
    if (livesDisplay) {
      let livesHTML = '';
      for (let i = 0; i < this.levelManager.lives; i++) {
        livesHTML += '<span style="color: #0ff;">&#9679;</span> ';
      }
      livesDisplay.innerHTML = `LIVES: ${livesHTML}`;
    }

    const levelDisplay = document.getElementById('level-display');
    if (levelDisplay) {
      levelDisplay.textContent = `LEVEL ${this.levelManager.level}`;
    }
  }

  public dispose(): void {
    if (this.animationId !== null) {
      cancelAnimationFrame(this.animationId);
    }
    this.input.stopPolling();
    this.audio.dispose();
    this.particleManager.dispose();
    this.shockwaveRing.dispose();
    this.floatingScoreText.dispose();
    this.postProcessing.dispose();
    this.renderer.dispose();
    window.removeEventListener('resize', this.handleResize);
  }

  private handleResize = (): void => {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.camera.aspect = width / height;
